import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Локализация","description":"","frontmatter":{"pageId":"developers/localization","contentRevision":2},"headers":[],"relativePath":"ru/developers/localization.md","filePath":"ru/developers/localization.md"}'),r={name:"ru/developers/localization.md"};function l(n,a,s,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="локализация" tabindex="-1">Локализация <a class="header-anchor" href="#локализация" aria-label="Permalink to &quot;Локализация&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Каждая пользовательская строка мода — keyed string в mod/Languages/English и Russian. Добавляй обе версии в одной задаче, используй одинаковые ключи и placeholders; не переводи технические id. Проверяй реальные окна, длину подписи и склонение в контексте.</p><p>Wiki использует одинаковые pageId и общие явные anchors в RU/EN. Обе статьи имеют одинаковый contentRevision. Изменение смысла требует обновить обе версии и manifest, а не заменить EN ссылкой на RU. Заголовки навигации тоже переводятся. Поиск локальный, нормализует регистр и ё/е.</p><p>Выполни test:checks и check:content после перевода; смысл, предупреждения и числовые ограничения сверяй вручную. Автоматическое совпадение metadata не доказывает качество перевода.</p><h2 id="translation-work" tabindex="-1">Проверка перевода как поведения <a class="header-anchor" href="#translation-work" aria-label="Permalink to &quot;Проверка перевода как поведения {#translation-work}&quot;">​</a></h2><p>Для нового UI сначала выбери ключ и смысл параметров, затем добавь English/Russian с одинаковыми placeholders. Проверь множественные формы, порядок подстановок, длину кнопок и предупреждение до опасного действия. Технические id, ключи конфигурации и пути не переводятся.</p><p>В wiki переводится весь сценарий, а не только заголовок. Сравни числа, предусловия, владельца действий и последствия отказа. Увеличь общий contentRevision и обнови coverage-вопросы/источники. Общие anchors сохраняют переключение языка с hash. Структурный PASS не умеет доказать смысловой перевод.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не добавляй строки непосредственно в C# UI вместо ключей. Не используй внешний поисковый сервис/аналитику ради перевода. Примеры не должны включать реальные токены, личные сейвы или приватные логи.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./contributing">Вклад и сопровождение wiki</a></li><li><a href="./testing">Тестирование и приёмка</a></li><li><a href="./../glossary">Словарь</a></li></ul>',13)])])}const m=e(r,[["render",l]]);export{u as __pageData,m as default};
